const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const availableTime = String(body.available_time || body.availableTime || 'unknown');
const preferredMode = String(body.preferred_mode || body.preferredMode || 'any');
const maxOptions = Math.min(Number(body.max_options || body.maxOptions || 3), 3);
const dryRun = body.dry_run !== false;

const prompt = [
  'Revisa el flujo operativo completo del proyecto Invernadero Central desde el estado versionado actual.',
  `Solicitud PMO: ${body.pmo_request || body.message || 'revisar flujo y recomendar siguiente accion'}.`,
  `Tiempo disponible humano: ${availableTime}.`,
  `Modo preferido: ${preferredMode}.`,
  `Maximo de opciones: ${maxOptions}.`,
  'Lee roadmap, backlog, epic-map, board Kanban, modelo operativo, roles expertos, baseline actual y draft de planificacion.',
  'Evalua WIP, bloqueos, dependencias, items que requieren refinamiento, evidencia pendiente, prioridades y fase del roadmap.',
  'Devuelve board_health, priority_assessment y recommended_next_actions con el agente recomendado para cada accion.',
  'Recomienda maximo 3 opciones. Si una opcion necesita desglose, enruta a project-refinement. Si necesita implementacion aprobada, enruta a project-engineering. Si necesita evidencia, enruta a project-qa-evidence.',
  'No muevas estados Kanban, no marques DONE, no edites HU congeladas, no apruebes compras ni control fisico.',
  'Si falta informacion, haz una sola pregunta.'
].join(' ');

return [{
  json: {
    agent: 'project-pmo',
    workspace: 'central',
    prompt,
    mode: 'draft',
    approval_required: true,
    dry_run: dryRun,
    metadata: {
      task_id: 'WF-PMO-CONTROL-001',
      agent_id: 'AGENT-PMO-001',
      available_time: availableTime,
      preferred_mode: preferredMode,
      max_options: maxOptions,
      requested_by: body.requested_by || 'chat-gateway'
    }
  }
}];
